/**
 * 发布单可投放设备数：型号与来源版本匹配、分桶号小于比例、未被隔离（ACTIVE）
 * 且在该发布单下尚无任务（与拉取创建新任务的条件一致）。
 */
public long countDeployableCandidates(long releaseId, String model, String fromVersion, int ratio) {
    Long count = jdbc.queryForObject(
            "SELECT COUNT(*) FROM device d WHERE d.model = ? AND d.current_version = ?"
                    + " AND d.bucket_no < ? AND d.status = 'ACTIVE'"
                    + " AND NOT EXISTS (SELECT 1 FROM rollout_task t"
                    + " WHERE t.release_id = ? AND t.device_id = d.device_id)",
            Long.class, model, fromVersion, ratio, releaseId);
    return count == null ? 0 : count;
}

