    @Test
    void 发布启动_全部候选设备隔离422_预检可查() throws Exception {
        registerDevice("r-d1", "d1", "m1", 1);
        registerDevice("r-d2", "d2", "m1", 2);
        quarantine("d1", "r-q1", "op1", "FAULT");
        quarantine("d2", "r-q2", "op1", "FAULT");

        // 预检：全部候选隔离，不可启动
